// ResolvePluginResult synchronously scrapes a source URL and ingests the full
// record, returning its canonical id. Unlike the async `scrape` mutation (which
// only queues a job), this blocks so the caller can open a populated detail page.
func (r *mutationResolver) ResolvePluginResult(ctx context.Context, pluginName string, url string, posterURL *string) (string, error) {
	plugin, ok := r.registry.Get(pluginName)
	if !ok {
		return "", fmt.Errorf("plugin %q not found", pluginName)
	}

	entity, ok := plugin.ContentFindEntity()
	if !ok {
		return "", fmt.Errorf("plugin %q has no find capability", pluginName)
	}
	results, err := r.runner.Find(ctx, plugin, entity, url)
	if err != nil {
		return "", err
	}

	// Some sources expose the poster only on the browse listing, not the detail
	// page. Backfill it from the caller so the record has an image.
	if posterURL != nil && *posterURL != "" {
		for _, result := range results {
			if result.Scene != nil && result.Scene.PosterPath == "" {
				result.Scene.PosterPath = *posterURL
			}
		}
	}

	ingestResult, err := r.ingestSvc.IngestScrapeResults(ctx, pluginName, url, results)
	if err != nil {
		return "", err
	}
	if ingestResult == nil || ingestResult.CanonicalID == "" {
		return "", fmt.Errorf("scrape produced no media record")
	}
	return ingestResult.CanonicalID, nil
}

