// PluginSearch backs live search: it fans out to every enabled
// search-capable plugin and returns their raw results (banner + preview frames)
// without touching the database. Selecting a result ingests it via the scrape mutation.
func (r *queryResolver) PluginSearch(ctx context.Context, query string, limit *int, pluginNames []string) ([]*model.PluginSearchResult, error) {
	if query == "" {
		return []*model.PluginSearchResult{}, nil
	}
	max := 20
	if limit != nil && *limit > 0 {
		max = *limit
	}

	// NSFW search only queries adult sources; SFW plugins never leak in.
	searchPlugins := adultPlugins(r.registry.WithAnyCapability(plugins.CapabilitySceneList, plugins.CapabilityGalleryList))
	searchPlugins = filterPluginsByName(searchPlugins, pluginNames)
	if len(searchPlugins) == 0 {
		return []*model.PluginSearchResult{}, nil
	}

	collected := r.fanOutSearch(ctx, searchPlugins, query, max)

	seen := make(map[string]bool)
	results := make([]*model.PluginSearchResult, 0, len(collected))
	toPersist := make([]discoveredItemWithPlugin, 0, len(collected))
	for _, entry := range collected {
		if seen[entry.item.ExternalID] {
			continue
		}
		seen[entry.item.ExternalID] = true
		results = append(results, pluginSearchResult(entry.plugin, entry.item))
		toPersist = append(toPersist, entry)
	}
	r.persistDiscoveredItems(toPersist)
	r.logSearch(query, pluginNames, len(results))
	return results, nil
}

// PluginBrowse backs the NSFW landing feed: the latest items from every enabled
// scene:list-capable plugin, mapped like search results.
func (r *queryResolver) PluginBrowse(ctx context.Context, limit *int, offset *int) ([]*model.PluginSearchResult, error) {
	max := 40
	if limit != nil && *limit > 0 {
		max = *limit
	}
	skip := 0
	if offset != nil && *offset > 0 {
		skip = *offset
	}

	browsePlugins := adultPlugins(r.registry.WithAnyCapability(plugins.CapabilitySceneList, plugins.CapabilityGalleryList))
	if len(browsePlugins) == 0 {
		return []*model.PluginSearchResult{}, nil
	}

	type pluginResult struct {
		name  string
		items []plugins.DiscoveredItem
	}
	ch := make(chan pluginResult, len(browsePlugins))

	for _, plugin := range browsePlugins {
		go func(plugin *plugins.Plugin) {
			entity, ok := plugin.ContentListEntity()
			if !ok {
				ch <- pluginResult{name: plugin.Meta.Name}
				return
			}
			result, err := r.runner.List(ctx, plugin, entity, plugins.ListArgs{Limit: max, Offset: skip})
			if err != nil {
				log.Printf("pluginBrowse via %s: %v", plugin.Meta.Name, err)
				ch <- pluginResult{name: plugin.Meta.Name}
				return
			}
			ch <- pluginResult{name: plugin.Meta.Name, items: result.Items}
		}(plugin)
	}

	seen := make(map[string]bool)
	results := make([]*model.PluginSearchResult, 0, len(browsePlugins)*max)
	toPersist := make([]discoveredItemWithPlugin, 0, len(browsePlugins)*max)
	for range browsePlugins {
		res := <-ch
		for _, item := range res.items {
			if seen[item.ExternalID] {
				continue
			}
			seen[item.ExternalID] = true
			results = append(results, pluginSearchResult(res.name, item))
			toPersist = append(toPersist, discoveredItemWithPlugin{plugin: res.name, item: item})
		}
	}
	r.persistDiscoveredItems(toPersist)
	return results, nil
}

